select wtd.*, wt.id wtId, wt.serial_number wtSN, wt.applicant_name wtfName, wt.reviewer_name wtrName, wt.review_time, wt.create_time wtcTime, CASE WHEN wt.transfer_create_type is null THEN 1 ELSE wt.transfer_create_type END as transfer_create_type, wt.party_a_borrow_id wtpaId, wt.borrow_project_id wtbpId, wt.direction_project_id wtdpid, wt.direction_workshop_id wtdfid, wt.direction_warehouse_id wtdwid, wt.outbound_id outId, wt.outbound_sn outSn, p3.id pid3, p3.short_name psName3, p3.serial_number pSN3, p3.name pn3, p2.id pid2, p2.short_name psName2, p2.serial_number pSN2, p2.name pn2, mbf2.id mbfId2, mbf2.name mbfName2, ww2.id wwId2, ww2.name wwName2, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, mbf.id mbfId, mbf.name mbfName, ww.id wwId, ww.name wwName from wms_transfer_detail wtd left join wms_transfer wt on wt.id = wtd.transfer_id left join contract_project p on p.id = wtd.source_project_id left join wms_workshop mbf on wtd.source_workshop_id = mbf.id left join wms_warehouse ww on ww.id = wtd.source_warehouse_id left join contract_project p2 on p2.id = wt.direction_project_id left join contract_project p3 on p3.id = wt.borrow_project_id left join wms_workshop mbf2 on wt.direction_workshop_id = mbf2.id left join wms_warehouse ww2 on ww2.id = wt.direction_warehouse_id where wtd.bool_delete_enum = 0 and wt.review_status = 2
and wtd.basic_class = #{basicClass}
and wtd.bool_party_a = 1
and wtd.bool_party_a = 0
and wtd.material_is_whole = #{materialIsWhole}
and (wtd.source_workshop_id = #{workshopId} or wt.direction_workshop_id = #{workshopId})
AND wtd.source_warehouse_id = #{warehouseId}
AND wtd.source_project_id = #{sourceProjectId}
AND wt.direction_project_id = #{directionProjectId}
and wt.review_time > #{reviewTime[0]}
and wt.review_time < #{reviewTime[1]}
and wtd.real_time > #{realTime[0]}
and wtd.real_time < #{realTime[1]}
and wt.serial_number like CONCAT('%', #{transferSN},'%')
and (wt.applicant_name like CONCAT('%', #{operatorName},'%') or wt.reviewer_name like CONCAT('%', #{operatorName},'%'))
and wtd.classify_id in
#{item}
and wtd.width = #{width}
and wtd.length = #{length}
-- 长度范围只用于钢卷查询,钢卷quantity计量量记录长度
and wtd.quantity >= #{minLength}
and wtd.quantity <= #{maxLength}
and wtd.theory_thickness = #{theoryThickness}
and wtd.thickness = #{thickness}
and wtd.color like CONCAT('%', #{color},'%')
and wtd.specification like CONCAT('%', #{specification},'%')
and wtd.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
AND wtd.brand like CONCAT('%',#{brand},'%')
AND wt.transfer_type = #{transferType}
and wtd.source_workshop_id in
#{item}
and (wt.transfer_create_type = 1 or wt.transfer_create_type is null)
and wt.transfer_create_type = 2
and wt.outbound_sn like CONCAT('%', #{outboundSn},'%')

        select *
        from wms_transfer_detail
        where bool_delete_enum = 0
        
            and basic_class = #{basicClass}
        
        
            and workshop_id = #{workshopId}
        
        
            AND warehouse_id = #{warehouseId}
        
        
            AND material_is_whole = #{materialIsWhole}
        
        
            
                and review_time > #{createTime[0]}
            
            
                and review_time < #{createTime[1]}
            
        
        
            and classify_id in
            
                #{item}
            
        
        
            and classify_id = #{classifyId}
        
        
