select
wtd.*,
wt.id wtid,
wt.review_time,
wt.serial_number wsn,
wt.applicant_name wa,
p.id pid,
p.short_name psName,
p.serial_number pSN,
p.name pn,
mbf.id mbfId,
mbf.name mbfName,
ww.id wwId,
ww.name wwName
from
wms_transfer_detail wtd
left join wms_transfer wt on wtd.transfer_id = wt.id
left join contract_project p on p.id = wtd.source_project_id
left join wms_workshop mbf on wtd.source_workshop_id = mbf.id
left join wms_warehouse ww on ww.id = wtd.source_warehouse_id
where
wtd.bool_delete_enum = 0
and wt.review_status = 2
and wt.transfer_type = 4

    and wtd.source_workshop_id = #{workshopId}


    and wtd.source_warehouse_id = #{warehouseId}


    and wtd.source_project_id = #{projectId}


    and wtd.basic_class & #{ basicClass} > 0


    AND wtd.material_is_whole = #{materialIsWhole}


    and wtd.classify_id in
    
        #{item}
    


    and wtd.classify_id = #{classifyId}


    
        and wtd.create_time > #{createTime[0]}
    
    
        and wtd.create_time < #{createTime[1]}
    


    and wtd.width = #{width}


    and wtd.length = #{length}

-- 长度范围只用于钢卷查询,钢卷quantity计量量记录长度

    and wtd.quantity >= #{minLength}


    and wtd.quantity <= #{maxLength}


    and wtd.theory_thickness = #{theoryThickness}


    and wtd.thickness = #{thickness}


    and wtd.color like CONCAT('%', #{color},'%')


    and wtd.specification like CONCAT('%', #{specification},'%')


    and wtd.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')


    AND wtd.brand like CONCAT('%',#{brand},'%')


    and wtd.source_workshop_id in
    
        #{item}

select wtd.*, wc.name classifyName, wt.review_time wrt, wm.*, p.short_name spName, p2.short_name dpName, p.name spName, p2.name dpName, pm.name pmName, pa.name paName, pm2.name pm2Name, pa2.name pa2Name, wt.transfer_type wtType, wt.serial_number wtSN, wt.outbound_sn outSN, ww.name warehouseName, wwh.name directionWareHouseName from wms_transfer_detail wtd left join wms_transfer wt on wt.id = wtd.transfer_id left join contract_project p on p.id = wtd.source_project_id left join contract_project p2 on p2.id = wt.direction_project_id left join wms_classification wc on wtd.classify_id = wc.id left join wms_measure wm on wm.classification_id = wtd.classify_id left join plan_monomer pm on pm.id = wtd.source_monomer_id left join plan_area pa on pa.id = wtd.source_area_id left join plan_monomer pm2 on pm2.id = wt.direction_monomer_id left join plan_area pa2 on pa2.id = wt.direction_area_id left join wms_warehouse ww on ww.id=wtd.source_warehouse_id left join wms_warehouse wwh on wwh.id=wt.direction_warehouse_id where wtd.bool_delete_enum = 0 and wt.review_status = 2
and wtd.real_time > #{param.realTime[0]}
and wtd.real_time < #{param.realTime[1]}
