wms_transfer_detail wtd
left join wms_transfer wt on wtd.transfer_id = wt.id
left join contract_project p on p.id = wtd.source_project_id
left join wms_workshop mbf on wtd.source_workshop_id = mbf.id
left join wms_warehouse ww on ww.id = wtd.source_warehouse_id
where
wtd.bool_delete_enum = 0
and wt.review_status = 2
and wt.transfer_type = 4

    and wtd.source_workshop_id = #{workshopId}


    and wtd.source_warehouse_id = #{warehouseId}


    and wtd.source_project_id = #{projectId}


    and wtd.basic_class & #{ basicClass} > 0


