        sum(wtd.amount_excluding_VAT) as amountExcludingVatCount
        from wms_transfer_detail wtd
        left join wms_transfer wt on wt.id = wtd.transfer_id
        left join contract_project p on p.id = wtd.source_project_id
        left join wms_warehouse ww on ww.id = wtd.source_warehouse_id
